#!/usr/bin/env node
/**
 * Tests for the reader A trigger in workflows/dev-loop.js: a block gets reader A only when the run has a security or
 * data axis or the block's gate was red before green; a risky task alone no longer does.
 * A plan of five tasks is two blocks (size L). The shared harness is tools/dev-loop.harness.mjs.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run, ARGS_M, review, impl, gate, tasksOf } from './dev-loop.harness.mjs';

const readerAs = (calls) => calls.filter((c) => /reader A$/.test(c.opts.label ?? ''));
const greenAt = (tree) => impl({ gate: gate('green', { tree }) });
const FIVE = [review([]), review([]), review([]), review([]), review([])];
const plan = (risky) => ({ tasks: tasksOf(5).map((t) => ({ ...t, risky: risky(t) })) });

test('given a risky:true task and no security or data axis with green gates, when the loop runs, then reader A runs on no block', async () => {
  // Given
  const args = { ...ARGS_M, verify: 'node --test x', plan: plan((t) => t.id === 'T1') };

  // When
  const { out, calls } = await run(args, FIVE, [greenAt('tr1'), greenAt('tr2')]);

  // Then
  assert.equal(readerAs(calls).length, 0);
  assert.deepEqual(out.blocks.map((b) => b.readerA.skipped), [true, true]);
});

test('given a security axis and no risky task, when the loop runs, then reader A runs on every block', async () => {
  // Given
  const args = { ...ARGS_M, verify: 'node --test x', risk: ['security'], plan: plan(() => false) };

  // When
  const { calls } = await run(args, FIVE, [greenAt('tr1'), greenAt('tr2')]);

  // Then
  assert.equal(readerAs(calls).length, 2);
});

test('given a data axis and no risky task, when the loop runs, then reader A runs on every block', async () => {
  // Given
  const args = { ...ARGS_M, verify: 'node --test x', risk: ['data'], plan: plan(() => false) };

  // When
  const { calls } = await run(args, FIVE, [greenAt('tr1'), greenAt('tr2')]);

  // Then
  assert.equal(readerAs(calls).length, 2);
});

test('given no risky task and a block gate red before green, when the loop runs, then reader A runs on that block only', async () => {
  // Given
  const args = { ...ARGS_M, verify: 'node --test x', plan: plan(() => false) };

  // When
  const { out, calls } = await run(args, FIVE, [impl({ gate: gate('red', { tree: 'tr0' }) }), greenAt('tr1'), greenAt('tr2')]);

  // Then
  assert.deepEqual(out.blocks.map((b) => !!b.readerA.skipped), [false, true]);
  assert.equal(readerAs(calls).length, 1);
});
